## Professional Command-Line Tools

### Argument Parsing

```xiom
use xiom.cli;

fn main() -> Int {
  let args = cli::App::new("mytool")
    .version("1.0.0")
    .author("Your Name")
    .about("Does amazing things")
    .arg(
      cli::Arg::new("input")
        .help("Input file to process")
        .required(true)
    )
    .arg(
      cli::Arg::new("output")
        .short('o')
        .long("output")
        .help("Output file (default: stdout)")
    )
    .arg(
      cli::Arg::new("verbose")
        .short('v')
        .long("verbose")
        .action(cli::ArgAction::Count)
        .help("Increase verbosity")
    )
    .get_matches();

  let input = args.get::<Str>("input").unwrap();
  let verbose = args.get_count("verbose");

  io.println("Processing: " + input);
  return 0;
}
```

### Colored Output

```xiom
use xiom.term;

// Basic colors
term::println(term::Color::Green, "✓ Success");
term::println(term::Color::Red, "✗ Error");
term::println(term::Color::Yellow, "⚠ Warning");
term::println(term::Color::Blue, "ℹ Info");

// Styled text
let style = term::Style::new()
  .fg(term::Color::White)
  .bg(term::Color::Blue)
  .bold(true);
term::println_styled(style, " IMPORTANT ");

// Detect terminal support
if term::supports_color() {
  term::println(term::Color::Green, "Color supported!");
} else {
  io.println("No color support");
}
```

### Progress Bars

```xiom
use xiom.progress;

fn process_files(files: &Vec[Str]) {
  let bar = progress::Bar::new(files.len());
  bar.set_style("[{bar:40}] {percent}% {pos}/{len}");

  for file in files {
    process_file(file);
    bar.inc(1);
  }

  bar.finish_with_message("Done!");
}

// Spinner for indeterminate progress
let spinner = progress::Spinner::new();
spinner.set_message("Connecting...");
spinner.set_style(progress::SpinnerStyle::Dots);

let connection = connect()?;
spinner.finish_with_message("Connected!");
```

### Interactive Prompts

```xiom
use xiom.dialog;

// Confirm
if dialog::confirm("Proceed with installation?")? {
  install();
}

// Input
let name = dialog::input("Enter your name:")?;

// Password (hidden input)
let password = dialog::password("Enter password:")?;

// Select from list
let choice = dialog::select("Choose environment:", &[
  "development",
  "staging",
  "production",
])?;

// Multi-select
let features = dialog::multi_select("Select features:", &[
  "authentication",
  "analytics",
  "notifications",
  "backup",
])?;
```

### Tables

```xiom
use xiom.table;

let mut table = table::Table::new();
table.set_header(["ID", "Name", "Status"]);
table.add_row(["1", "Alice", "Active"]);
table.add_row(["2", "Bob", "Inactive"]);
table.add_row(["3", "Charlie", "Active"]);
table.print();

// Output:
// ┌────┬─────────┬──────────┐
// │ ID │ Name    │ Status   │
// ├────┼─────────┼──────────┤
// │ 1  │ Alice   │ Active   │
// │ 2  │ Bob     │ Inactive │
// │ 3  │ Charlie │ Active   │
// └────┴─────────┴──────────┘
```

### Exit Codes

```xiom
fn main() -> Int {
  match run_app() {
    Ok(()) => 0,
    Err(e) => {
      term::eprintln(term::Color::Red, "Error: " + e.to_str());
      1  // Non-zero exit code
    },
  }
}
```

